<!--
  文本输入框: 只做行为与最小外观 —— 未聚焦 / 禁用等状态交给浏览器, 宽度由调用方的类名或外部布局
  决定 (`styles.css` 里已有针对 `.settings-content input` 等位置的既有规则)。

  可选前置图标 (`icon`) 必须落在**边框以内**, 因此给了图标时会多包一层 `.ui-input-group` 由它承担
  边框与聚焦环, 内层输入框只留文字; 没给图标时 DOM 与其余调用点 (诊断筛选、设置、仓库页) 完全一样。
-->

<script lang="ts">
  import Icon from './Icon.svelte';
  import type { IconName } from './icons';

  let {
    value = $bindable(''),
    type = 'text',
    placeholder,
    title,
    disabled = false,
    /** 允许换行的多行输入 */
    multiline = false,
    rows = 3,
    /** 挂载后自动聚焦并全选 (重命名对话框用) */
    autofocus = false,
    /** 只选中主文件名部分 (不含扩展名) */
    selectStem = false,
    /** 左侧前置图标 (与 `Button` 的 `icon` 同一套语义名) */
    icon,
    /** 给了 `icon` 时它落在承载边框的容器上, 否则落在输入框本身 */
    className = '',
    oninput,
    onkeydown,
  }: {
    value?: string;
    type?: 'text' | 'password' | 'search' | 'number';
    placeholder?: string;
    title?: string;
    disabled?: boolean;
    multiline?: boolean;
    rows?: number;
    autofocus?: boolean;
    selectStem?: boolean;
    icon?: IconName;
    className?: string;
    oninput?: (event: Event) => void;
    onkeydown?: (event: KeyboardEvent) => void;
  } = $props();

  let element: HTMLInputElement | HTMLTextAreaElement | undefined = $state();

  $effect(() => {
    if (!autofocus || !element) return;
    element.focus();
    if (selectStem && element.value) {
      const dot = element.value.lastIndexOf('.');
      element.setSelectionRange(0, dot > 0 ? dot : element.value.length);
    } else if (element instanceof HTMLInputElement) {
      element.select();
    }
  });
</script>

{#if multiline}
  <textarea
    bind:this={element}
    bind:value
    class="ui-input ui-textarea {className}"
    {rows}
    {placeholder}
    {title}
    {disabled}
    {oninput}
    {onkeydown}></textarea>
{:else if icon}
  <div class="ui-input-group {className}">
    <span class="ui-input-before" aria-hidden="true">
      <Icon name={icon} size={16} />
    </span>
    <input
      bind:this={element}
      bind:value
      class="ui-input ui-input-adorned"
      {type}
      {placeholder}
      {title}
      {disabled}
      {oninput}
      {onkeydown}
    />
  </div>
{:else}
  <input
    bind:this={element}
    bind:value
    class="ui-input {className}"
    {type}
    {placeholder}
    {title}
    {disabled}
    {oninput}
    {onkeydown}
  />
{/if}
